import{_ as p,a0 as e,w as b,s as i,ao as o,I as s,x as u,a1 as r,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"Ubuntu 所有版本的吉祥物 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 所有版本的吉祥物 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 所有版本的吉祥物 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 所有版本的吉祥物 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20220519 For the Love of Ubuntu- Here are the Mascots of All Ubuntu Releases","title":"Ubuntu 所有版本的吉祥物","tag":"202211","desc":""},"relativePath":"202211/20220519 For the Love of Ubuntu- Here are the Mascots of All Ubuntu Releases.md","filePath":"[post].md"}'),l={name:"202211/20220519 For the Love of Ubuntu- Here are the Mascots of All Ubuntu Releases.md"};function c(h,t,m,d,g,U){const a=e("Link");return b(),i("div",null,[t[18]||(t[18]=o('<h1 id="ubuntu-所有版本的吉祥物" tabindex="-1">Ubuntu 所有版本的吉祥物 <a class="header-anchor" href="#ubuntu-所有版本的吉祥物" aria-label="Permalink to “Ubuntu 所有版本的吉祥物”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202211/11/130502q6500yvm0znvktz9.jpg" alt=""></p><blockquote><p>在这篇文章中，我们会介绍迄今为止所有 Ubuntu 发行版本的吉祥物。</p></blockquote><p>你可能已经注意到了：每个 Ubuntu 版本都会有一个版本名称和代号。代号由两个单词组成，这两个单词有相同的首字母，第一个单词是形容词，另一个单词通常是一个濒危的物种名称。</p><p>对应于其代号，这些 Ubuntu 版本也有一个吉祥物。例如，Ubuntu 22.04 的代号为 “Jammy Jellyfish”，因此 Ubuntu 22.04 的桌面壁纸上有 <strong>吉祥物：水母</strong> 的图像。</p><p>但是实际上，这些“吉祥物”并不总是 Ubuntu 版本的一部分，因为吉祥物在早期的 Ubuntu 版本中是没有的。</p><p>有史以来第一个 Ubuntu 版本是在 2004 年 10 月发布的 4.10 版（LCTT 译注：Ubuntu 的版本号是由年份和月份的组合来表示的。）但是，直到 Ubuntu 8.04 LTS “Hardy Heron” 版本，你才会看到相关的吉祥物。</p>',7)),s("p",null,[t[1]||(t[1]=u("在我之前写的 ",-1)),r(a,{href:"https://itsfoss.com/Ubuntu-default-wallpapers-download/"},{default:n(()=>[...t[0]||(t[0]=[u("另一篇文章",-1)])]),_:1}),t[2]||(t[2]=u(" 中，我整理了所有 Ubuntu 版本的默认壁纸。在本文中，你将了解到所有 Ubuntu 版本的吉祥物。",-1))]),t[19]||(t[19]=o('<p>现在，就让我们按时间倒序，一起进入 Ubuntu 的吉祥物之旅吧。</p><p>（LCTT 校注：本文原文发表时，Ubuntu 22.10 尚未发布，它的代号是 “Kinetic Kudu”，吉祥物是“捻角羚”。）</p><p>（LCTT 校注：由于 Ubuntu 系列的代号和吉祥物选择的都是比较少见的动物和晦涩的描述，因此尽管译者和校对虽然尽力了，但是应该还有谬误。我觉得原文作者为了找出这些说明也尽力，恐怕真正权威的诠释只有 Canonical 才能给出吧。）</p><h3 id="ubuntu-22-04-jammy-jellyfish-幸运水母" tabindex="-1">Ubuntu 22.04 Jammy Jellyfish（幸运水母） <a class="header-anchor" href="#ubuntu-22-04-jammy-jellyfish-幸运水母" aria-label="Permalink to “Ubuntu 22.04 Jammy Jellyfish（幸运水母）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-22-04-mascot.jpg" alt="Ubuntu 22.04 mascot"></p><p>于 2021 年 4 月 21 日发布。</p><p>Jammy 的意思是被果酱覆盖着的、充满果酱的。不太正式地，Jammy 还有<strong>幸运</strong>的意思。</p><p><ruby>水母<rt> Jellyfish </rt></ruby> 是一种自由游动的水生动物，它的身体就像是一把透明伞，还具有拖曳的触须。少数水母是通过茎干固定在海床上，而不能移动。全世界的海洋中有超过两百种的水母，它们分布于全球各地的水域里。</p><h3 id="ubuntu-21-10-impish-indri-顽皮大狐猴" tabindex="-1">Ubuntu 21.10 Impish Indri（顽皮大狐猴） <a class="header-anchor" href="#ubuntu-21-10-impish-indri-顽皮大狐猴" aria-label="Permalink to “Ubuntu 21.10 Impish Indri（顽皮大狐猴）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-21-10-mascot.jpg" alt="Ubuntu 21.10 mascot"></p><p>于 2021 年 10 月 14 日发布。</p><p>Impish 的意思是以<strong>顽皮</strong>而不是严肃的方式，对某人/某事不太尊重。</p><p><ruby>大狐猴<rt> Indri </rt></ruby>，也称为 babakoto，是现存的最大的狐猴之一。它的头身长约 64 至 72 厘米，体重在 6 至 9.5 公斤之间。它的毛发是黑白相间的。在攀爬或攀爬时，它会保持竖直的姿势。</p><blockquote><p>据维基：2014 年的世界自然保护联盟（IUCN） <ruby>红色名录<rt> Red List </rt></ruby> 中，仅出现在马达加斯加的大狐猴首次被提升至极危级别。</p></blockquote><h3 id="ubuntu-21-04-hirsute-hippo-多毛河马" tabindex="-1">Ubuntu 21.04 Hirsute Hippo（多毛河马） <a class="header-anchor" href="#ubuntu-21-04-hirsute-hippo-多毛河马" aria-label="Permalink to “Ubuntu 21.04 Hirsute Hippo（多毛河马）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-21-04-mascot.jpg" alt="Ubuntu 21.04 mascot"></p><p>于 2021 年 4 月 22 日发布。</p><p>Hirsute 的意思是<strong>多毛的</strong>。</p><p><ruby>河马<rt> Hippo </rt></ruby>，是一种生活在非洲大陆撒哈拉以南的大型半水生哺乳动物。河马是河马科中仅有的两个现存物种之一，另一个物种是 <ruby>侏儒河马<rt> pygmy hippopotamus </rt></ruby>。河马的名字来源于古希腊语“river horse”。</p><blockquote><p>据维基：在 2006 年 5 月已被 IUCN 红色名录中分为易危物种，世界仅存约 12.5 万－15 万头</p></blockquote><p>但是其实，我并没有见过很多多毛的河马 😅。</p><h3 id="ubuntu-20-10-groovy-gorilla-时髦大猩猩" tabindex="-1">Ubuntu 20.10 Groovy Gorilla（时髦大猩猩） <a class="header-anchor" href="#ubuntu-20-10-groovy-gorilla-时髦大猩猩" aria-label="Permalink to “Ubuntu 20.10 Groovy Gorilla（时髦大猩猩）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-20-10-mascot.jpg" alt="Ubuntu 20.10 mascot"></p><p>于 2020 年 10 月 22 日发布。</p><p>Groovy 的意思是<strong>时尚的</strong>和令人兴奋的。</p><p><ruby>大猩猩<rt> Gorilla </rt></ruby>，是一种草​​食性的地栖巨猿。它主要栖息在赤道非洲的热带森林中。大猩猩属分为两个物种：东部大猩猩和西部大猩猩，以及进一步可分为四个或五个亚种。</p><h3 id="ubuntu-20-04-lts-focal-fossa-瞩目狸猫" tabindex="-1">Ubuntu 20.04 LTS Focal Fossa（瞩目狸猫） <a class="header-anchor" href="#ubuntu-20-04-lts-focal-fossa-瞩目狸猫" aria-label="Permalink to “Ubuntu 20.04 LTS Focal Fossa（瞩目狸猫）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-20-04-mascot-1.jpg" alt="Ubuntu 20.04 mascot"></p><p>于 2020 年 4 月 23 日发布。</p><p>Focal 的意思是令人注目的、<strong>瞩目</strong>。</p><p><ruby>马岛长尾狸猫<rt> Fossa </rt></ruby>，是<strong>马达加斯加岛上最大的食肉性哺乳动物</strong>。它身体的长度可以达到近六英尺，其中它们的长尾巴占了一半。它们看起来就像是猫、狗和獴的杂交体。它们有细长的身体、肌肉发达的四肢和短的红棕色毛发。</p><h3 id="ubuntu-19-10-eoan-ermine-东方白鼬" tabindex="-1">Ubuntu 19.10 Eoan Ermine（东方白鼬） <a class="header-anchor" href="#ubuntu-19-10-eoan-ermine-东方白鼬" aria-label="Permalink to “Ubuntu 19.10 Eoan Ermine（东方白鼬）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-19-10-mascot.jpg" alt="Ubuntu 19.10 mascot"></p><p>于 2019 年 10 月 17 日发布。</p><p>Eoan 的意思是<strong>与黎明或东方有关的</strong>。</p><p><ruby>白鼬<rt> Stoat </rt></ruby>，也被称为欧亚貂、白令貂，简称 <ruby>貂<rt> Ermine </rt></ruby>，是一种原产于欧亚大陆和北美北部的鼬科动物。由于鼬在极地广泛分布，因此它被 IUCN 列为最不担忧灭绝的物种。</p><blockquote><p>据维基：IUCN 将其列为世界百大外来入侵种。</p></blockquote><h3 id="ubuntu-19-04-disco-dingo-迪斯科野犬" tabindex="-1">Ubuntu 19.04 Disco Dingo（迪斯科野犬） <a class="header-anchor" href="#ubuntu-19-04-disco-dingo-迪斯科野犬" aria-label="Permalink to “Ubuntu 19.04 Disco Dingo（迪斯科野犬）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-19-04-mascot.jpg" alt="Ubuntu 19.04 mascot"></p><p>于 2019 年 4 月 18 日发布。</p><p>Disco 与<strong>迪斯科</strong>音乐和夜总会有关。</p><p><ruby>澳洲野犬<rt> Dingo </rt></ruby>，是在澳大利亚发现的一种古老的犬种。澳洲野犬的科属分类在不同出版物中不太一样，因此它的科属分类存在争议。</p><h3 id="ubuntu-18-10-cosmic-cuttlefish-外星墨鱼" tabindex="-1">Ubuntu 18.10 Cosmic Cuttlefish（外星墨鱼） <a class="header-anchor" href="#ubuntu-18-10-cosmic-cuttlefish-外星墨鱼" aria-label="Permalink to “Ubuntu 18.10 Cosmic Cuttlefish（外星墨鱼）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-18-10-mascot.jpg" alt="Ubuntu 18.10 mascot"></p><p>于 2018 年 10 月 18 日发布。</p><p>Cosmic 意味着与地球<strong>不同的</strong>、宇宙的。</p><p><ruby>墨鱼<rt> Cuttlefish </rt></ruby>，是乌贼目的一种海洋软体动物。它属于头足类，这一类还包含了鱿鱼、章鱼和鹦鹉螺。墨鱼有一个独特的内壳，即墨鱼骨，它可以用于控制浮力。</p><h3 id="ubuntu-18-04-lts-bionic-beaver-仿生河狸" tabindex="-1">Ubuntu 18.04 LTS Bionic Beaver（仿生河狸） <a class="header-anchor" href="#ubuntu-18-04-lts-bionic-beaver-仿生河狸" aria-label="Permalink to “Ubuntu 18.04 LTS Bionic Beaver（仿生河狸）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-18-04-mascot.jpg" alt="Ubuntu 18.04 mascot"></p><p>于 2018 年 4 月 26 日发布。</p><p>Bionic 意味着<strong>仿生的</strong>，或者是机电的。</p><p><ruby>河狸<rt> Beaver </rt></ruby>，是北半球温带的一种大型半水生啮齿动物。有两种现存的海狸：北美河狸和欧亚河狸。河狸是仅次于水豚的现存第二大啮齿动物。</p><blockquote><p>据维基：它们处于 IUCN 哺乳动物红色名录中的无危物种，在中国河狸被列为一级保护动物。</p></blockquote><p>英国用户认为这个版本的名称特别有趣。</p><h3 id="ubuntu-17-10-artful-aardvark-机灵土豚" tabindex="-1">Ubuntu 17.10 Artful Aardvark（机灵土豚） <a class="header-anchor" href="#ubuntu-17-10-artful-aardvark-机灵土豚" aria-label="Permalink to “Ubuntu 17.10 Artful Aardvark（机灵土豚）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-17-10-mascot.jpg" alt="Ubuntu 17.10 mascot"></p><p>于 2017 年 10 月 19 日发布。</p><p>Ubuntu 在此版本中默认切换回了 GNOME。</p><p>Artful 的意思是聪明的或<strong>机灵的</strong>。</p><p><ruby>土豚<rt> Aardvark </rt></ruby>，是一种原产于非洲的穴居、夜间活动的中型哺乳动物。它是管齿目中唯一的现存物种。与大多数其他食虫动物不同，它有一个长长的像猪一样的鼻子，可以闻出食物在哪里。</p><h3 id="ubuntu-17-04-zesty-zapus-开心跳鼠" tabindex="-1">Ubuntu 17.04 Zesty Zapus（开心跳鼠） <a class="header-anchor" href="#ubuntu-17-04-zesty-zapus-开心跳鼠" aria-label="Permalink to “Ubuntu 17.04 Zesty Zapus（开心跳鼠）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-17-04-mascot.jpg" alt="Ubuntu 17.04 mascot"></p><p>于 2017 年 4 月 13 日发布。</p><p>这个版本是最后一个以 Unity 桌面为特色的版本。</p><p>Zesty 意味着有一种强烈的、<strong>令人开心的</strong>、有点辛辣的味道。</p><p><ruby>跳鼠<rt>Zapus</rt></ruby> 是北美跳鼠中唯一一个有牙齿的一个属。跳鼠是除 <ruby>指猴<rt> Aye-aye </rt></ruby>之外，唯一现存的有 18 颗牙齿的哺乳动物。</p><h3 id="ubuntu-16-10-yakkety-yak-唠叨牦牛" tabindex="-1">Ubuntu 16.10 Yakkety Yak（唠叨牦牛） <a class="header-anchor" href="#ubuntu-16-10-yakkety-yak-唠叨牦牛" aria-label="Permalink to “Ubuntu 16.10 Yakkety Yak（唠叨牦牛）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-16-10-mascot.jpg" alt="Ubuntu 16.10 mascot"></p><p>于 2016 年 10 月 13 日发布。</p><p>Yakkety 有很多意思。OMG Ubuntu 说，“yakking” 有唠唠叨叨这一非正式意思，yakkety 还可能是一种知名的流行爵士乐器 “Yakety Sax” 的另一种拼写。</p><p><ruby>牦牛<rt> Yak </rt></ruby>，是一种大型驯养的野牛。它的毛发蓬松，肩部隆起，有很大的角。在一些地方它是一种驮畜，人们也可以食用它的奶和肉、以及加工它的皮制作东西。</p><h3 id="ubuntu-16-04-lts-xenial-xerus-好客地松鼠" tabindex="-1">Ubuntu 16.04 LTS Xenial Xerus（好客地松鼠） <a class="header-anchor" href="#ubuntu-16-04-lts-xenial-xerus-好客地松鼠" aria-label="Permalink to “Ubuntu 16.04 LTS Xenial Xerus（好客地松鼠）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-16-04-mascot.jpg" alt="Ubuntu 16.04 mascot"></p><p>于 2016 年 4 月 21 日发布。</p><p>Xenial 的意思是<strong>热情好客的</strong>。</p><p><ruby>非洲地松鼠<rt> Xerus </rt></ruby>，有四个亚种，分别是<strong>开普地松鼠，条纹地松鼠，山地松鼠和无条纹地松鼠</strong>。这些动物是昼行性的，是食草动物，通常吃坚果、根和种子。然而，有时它们也会吃蛋类和其他小动物。</p><h3 id="ubuntu-15-10-wily-werewolf-狡猾狼人" tabindex="-1">Ubuntu 15.10 Wily Werewolf（狡猾狼人） <a class="header-anchor" href="#ubuntu-15-10-wily-werewolf-狡猾狼人" aria-label="Permalink to “Ubuntu 15.10 Wily Werewolf（狡猾狼人）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-15-10-mascot.jpg" alt="Ubuntu 15.10 mascot"></p><p>于 2015 年 10 月 22 日发布。</p><p>这个版本可能是少有的发布代号中带有虚构动物的 Ubuntu 版本之一。</p><p>Wily 的意思是善于获得优势，尤其在欺骗上十分<strong>狡猾的</strong>。</p><p><ruby>狼人<rt> Werewolf </rt></ruby>，是可以隐藏住耳朵和尾巴的一种神话生物。它是人，也是狼，大多数人因为它们的长相而害怕它们。</p><h3 id="ubuntu-15-04-vivid-vervet-活泼绿猴" tabindex="-1">Ubuntu 15.04 Vivid Vervet（活泼绿猴） <a class="header-anchor" href="#ubuntu-15-04-vivid-vervet-活泼绿猴" aria-label="Permalink to “Ubuntu 15.04 Vivid Vervet（活泼绿猴）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-15-04-mascot.jpg" alt="Ubuntu 15.04 mascot"></p><p>于 2015 年 4 月 23 日发布。</p><p>Vivid 的意思是<strong>活泼</strong>的、明亮的。</p><p><ruby>黑长尾猴<rt> Vervet monkey </rt></ruby>，是一种原产于非洲的角猿科的旧大陆猴。“vervet”一词也用于表示<ruby>绿猴属<rt> Chlorocebus </rt></ruby>的所有动物，其中包含五个不同的亚种，这五个不同的亚种主要分布在南部非洲以及一些东部国家。</p><h3 id="ubuntu-14-10-utopic-unicorn-乌托邦独角兽" tabindex="-1">Ubuntu 14.10 Utopic Unicorn（乌托邦独角兽） <a class="header-anchor" href="#ubuntu-14-10-utopic-unicorn-乌托邦独角兽" aria-label="Permalink to “Ubuntu 14.10 Utopic Unicorn（乌托邦独角兽）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-14-10-mascot.jpg" alt="Ubuntu 14.10 mascot"></p><p>于 2014 年 10 月 23 日发布。</p><p>这个版本是另一个其发布代号中带有虚构动物的 Ubuntu 版本。</p><p>Utopic 与<strong>乌托邦</strong>有关，乌托邦是一个虚构的、不存在但是一个理想的地方。</p><p><ruby>独角兽<rt> Unicorn </rt></ruby>，是一种传说中的生物。自古以来，它就被描述为前额有一个巨大的、尖的、螺旋状的角的一种野兽。</p><h3 id="ubuntu-14-04-lts-trusty-tahr-可靠塔尔羊" tabindex="-1">Ubuntu 14.04 LTS Trusty Tahr（可靠塔尔羊） <a class="header-anchor" href="#ubuntu-14-04-lts-trusty-tahr-可靠塔尔羊" aria-label="Permalink to “Ubuntu 14.04 LTS Trusty Tahr（可靠塔尔羊）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-14-04-mascot.jpg" alt="Ubuntu 14.04 mascot"></p><p>于 2014 年 4 月 17 日发布。</p><p>Trusty 意味着<strong>可靠的</strong>或忠实的。</p><p><ruby>塔尔羊<rt> Tahr </rt></ruby>，是一种很像山羊的哺乳动物。它们会栖息在阿曼、印度南部和喜马拉雅山脉的悬崖和山坡上。</p><h3 id="ubuntu-13-10-saucy-salamander-活泼蝾螈" tabindex="-1">Ubuntu 13.10 Saucy Salamander（活泼蝾螈） <a class="header-anchor" href="#ubuntu-13-10-saucy-salamander-活泼蝾螈" aria-label="Permalink to “Ubuntu 13.10 Saucy Salamander（活泼蝾螈）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-13-10-mascot.jpg" alt="Ubuntu 13.10 mascot"></p><p>于 2013 年 10 月 17 日发布。</p><p>Saucy 意味着大胆的、<strong>活泼的</strong>或精神饱满的。</p><p><ruby>蝾螈<rt> Salamander </rt></ruby>是一类两栖动物。其典型特征是有着蜥蜴般的外观，它们有细长的身体，钝的鼻子，以及与身体成直角突出的短肢，并且幼体和成体都有尾巴。现存的所有十个蝾螈科都属于有尾目。</p><h3 id="ubuntu-13-04-raring-ringtail-热情猫熊" tabindex="-1">Ubuntu 13.04 Raring Ringtail（热情猫熊） <a class="header-anchor" href="#ubuntu-13-04-raring-ringtail-热情猫熊" aria-label="Permalink to “Ubuntu 13.04 Raring Ringtail（热情猫熊）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-13-04-mascot.jpg" alt="Ubuntu 13.04 mascot"></p><p>于 2013 年 4 月 25 日发布。</p><p>Raring 的意思是热情的和<strong>非常渴望做某事</strong>。</p><p><ruby>猫熊<rt> Ringtail </rt></ruby>，是<strong>一种像猫一样大的食肉动物，类似于一只长着浣熊尾巴的小狐狸</strong>。它浓密的尾巴是扁平的，几乎和头部和身体一样长，有黑白交替的环。它们是夜行动物，一天中的大部分时间都在它们的巢穴里睡觉。</p><h3 id="ubuntu-12-10-quantal-quetzal-量子大咬鹃" tabindex="-1">Ubuntu 12.10 Quantal Quetzal（量子大咬鹃） <a class="header-anchor" href="#ubuntu-12-10-quantal-quetzal-量子大咬鹃" aria-label="Permalink to “Ubuntu 12.10 Quantal Quetzal（量子大咬鹃）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-12-10-mascot.jpg" alt="Ubuntu 12.10 mascot"></p><p>于 2012 年 10 月 18 日发布。</p><p>Quantal 意味着与<strong>量子</strong>或量子理论有关的。</p><p><ruby>大咬鹃<rt> Quetzal </rt></ruby>，是咬鹃家族中的一种色彩鲜艳的鸟类。它们生活在森林中，主要是在潮湿的高地。来自<em>凤尾绿咬鹃属</em>的五种物种生活在新热带的，而另外一个物种，即角咬鹃，生活在墨西哥和美国最南端的局部地区。大咬鹃相当地大，它们的身体长度超过 32 厘米或者有 13 英寸长，比其他咬鹃科的物种都大。绚丽的大咬鹃因其鲜艳的色彩，而成为危地马拉的国鸟。</p><h3 id="ubuntu-12-04-lts-precise-pangolin-精准穿山甲" tabindex="-1">Ubuntu 12.04 LTS Precise Pangolin（精准穿山甲） <a class="header-anchor" href="#ubuntu-12-04-lts-precise-pangolin-精准穿山甲" aria-label="Permalink to “Ubuntu 12.04 LTS Precise Pangolin（精准穿山甲）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-12-04-mascot.jpg" alt="Ubuntu 12.04 mascot"></p><p>于 2012 年 4 月 26 日发布。</p><p>Precise 意味着能<strong>精确</strong>或准确地表达细节。</p><p><ruby>穿山甲<rt> Pangolin </rt></ruby>，有时被称为有鳞食蚁兽，是鳞甲目的一种哺乳动物。它现存的一个科是穿山甲科，有三个属：穿山甲亚属、长尾穿山甲亚属和地穿山甲亚属。穿山甲亚属包括在亚洲发现的四种物种，而长尾穿山甲亚属和地穿山甲亚属各包括两种物种，均在撒哈拉以南非洲发现。</p><blockquote><p>据维基百科：2014 年，IUCN 红色名录物种存续委员会穿山甲专门小组，指出穿山甲是目前全世界最常被走私买卖的哺乳动物。所有穿山甲都面临巨大的生存威胁，其中中华穿山甲和马来穿山甲被 IUCN 评估为“极危”物种，非法走私的活动极为猖獗。随着亚洲的 4 种穿山甲数量锐减，走私贸易商家已转移目标至非洲，以满足市场上的庞大需求。</p></blockquote><h3 id="ubuntu-11-10-oneiric-ocelot-梦幻豹猫" tabindex="-1">Ubuntu 11.10 Oneiric Ocelot（梦幻豹猫） <a class="header-anchor" href="#ubuntu-11-10-oneiric-ocelot-梦幻豹猫" aria-label="Permalink to “Ubuntu 11.10 Oneiric Ocelot（梦幻豹猫）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-11-10-mascot.jpg" alt="Ubuntu 11.10 mascot"></p><p>于 2011 年 10 月 13 日发布。</p><p>Oneiric 的意思是与<strong>梦</strong>有关的。</p><p><ruby>豹猫<rt> Ocelot </rt></ruby>，是一种中等大小的斑点野猫。它的肩长可达 40 至 50 厘米，体重在 8 至 15.5 公斤之间。<ruby>卡尔·林奈<rt>Carl Linnaeus</rt></ruby> 于 1758 年首次在书中描述了它。</p><blockquote><p>据维基：华盛顿公约将孟加拉国、印度以及泰国的豹猫族群列入附录一禁止进行国际贸易，而其他族群亦列入华盛顿公约附录二。</p></blockquote><h3 id="ubuntu-11-04-natty-narwhal-聪明独角鲸" tabindex="-1">Ubuntu 11.04 Natty Narwhal（聪明独角鲸） <a class="header-anchor" href="#ubuntu-11-04-natty-narwhal-聪明独角鲸" aria-label="Permalink to “Ubuntu 11.04 Natty Narwhal（聪明独角鲸）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-11-04-mascot.jpg" alt="Ubuntu 11.04 mascot"></p><p>于 2011 年 4 月 28 日发布。</p><p>这个版本是第一个采用 Unity 桌面的版本。</p><p>Natty 意味着<strong>聪明</strong>和时尚的。</p><p><ruby>独角鲸<rt> Narwhal </rt></ruby>，是一种中等大小的齿鲸。拥有一颗突出的犬齿的大“獠牙”。它常年生活在格陵兰、加拿大和俄罗斯周围的北极水域。它是一角鲸科中现存的两种鲸鱼物种之一，另一个物种是 <ruby>白鲸<rt> Beluga whale </rt></ruby>。</p><h3 id="ubuntu-10-10-maverick-meerkat-独行猫鼬" tabindex="-1">Ubuntu 10.10 Maverick Meerkat（独行猫鼬） <a class="header-anchor" href="#ubuntu-10-10-maverick-meerkat-独行猫鼬" aria-label="Permalink to “Ubuntu 10.10 Maverick Meerkat（独行猫鼬）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-10-10-mascot.jpg" alt="Ubuntu 10.10 mascot"></p><p>于 2010 年 10 月 10 日发布。</p><p>Maverick 的意思是<strong>特立独行的</strong>或有独立思想的。</p><p><ruby>猫鼬<rt> Meerkat </rt></ruby>，是一种在南部非洲发现的小型猫鼬。它的特点是头宽、眼睛大、鼻子尖、腿长、尾巴很细，毛色有斑纹。</p><h3 id="ubuntu-10-04-lts-lucid-lynx-清醒猞狸" tabindex="-1">Ubuntu 10.04 LTS Lucid Lynx（清醒猞狸） <a class="header-anchor" href="#ubuntu-10-04-lts-lucid-lynx-清醒猞狸" aria-label="Permalink to “Ubuntu 10.04 LTS Lucid Lynx（清醒猞狸）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-10-04-mascot.jpg" alt="Ubuntu 10.04 mascot"></p><p>于 2010 年 4 月 29 日发布。</p><p>Lucid 意味着<strong>易于理解的</strong>或明亮的。</p><p><ruby>猞猁<rt> Lynx </rt></ruby>，是中型野猫属猞猁中的一种。猞猁这个名字起源于中古英语，源自希腊语 λύγξ，λύγξ 又源自于印欧语词根 leuk-，指的是它眼睛能反射发光的样子。</p><h3 id="ubuntu-9-10-karmic-koala-幸运考拉" tabindex="-1">Ubuntu 9.10 Karmic Koala（幸运考拉） <a class="header-anchor" href="#ubuntu-9-10-karmic-koala-幸运考拉" aria-label="Permalink to “Ubuntu 9.10 Karmic Koala（幸运考拉）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-9-10-mascot.jpg" alt="Ubuntu 9.10 mascot"></p><p>于 2009 年 10 月 29 日发布。</p><p>Karmic 意味着与<strong>命运</strong>、业力有关。</p><p><ruby>考拉<rt> Koala </rt></ruby>，是一种原产于澳大利亚的树栖草食性的有袋动物。它是袋鼠科唯一现存的物种，它的近亲是<ruby>袋熊<rt> Wombat </rt></ruby>。</p><blockquote><p>据维基：在 19 世纪初树袋熊遭到捕杀出口，数量由百万只锐减至一千多只，于是澳大利亚政府立法保护。</p></blockquote><h3 id="ubuntu-9-04-jaunty-jackalope-自信鹿角兔" tabindex="-1">Ubuntu 9.04 Jaunty Jackalope（自信鹿角兔） <a class="header-anchor" href="#ubuntu-9-04-jaunty-jackalope-自信鹿角兔" aria-label="Permalink to “Ubuntu 9.04 Jaunty Jackalope（自信鹿角兔）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-9-04-mascot.jpg" alt="Ubuntu 9.04 mascot"></p><p>于 2009 年 4 月 23 日发布。</p><p>这个版本是我用的第一个 Ubuntu 版本。</p><p>Jaunty 是指拥有活泼、开朗和<strong>自信</strong>的态度。</p><p><ruby>鹿角兔<rt> Jackalope </rt></ruby>，是<strong>北美民间传说中的一种神话动物</strong>，被描述为长着羚羊角的可怕的长角兔。Jackalope 这个词是由 jackrabbit 和 antelope 组合而成的。许多鹿角兔的标本都是由用鹿角制成的。</p><h3 id="ubuntu-8-10-intrepid-ibex-无畏野山羊" tabindex="-1">Ubuntu 8.10 Intrepid Ibex（无畏野山羊） <a class="header-anchor" href="#ubuntu-8-10-intrepid-ibex-无畏野山羊" aria-label="Permalink to “Ubuntu 8.10 Intrepid Ibex（无畏野山羊）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-8-10-mascot.jpg" alt="Ubuntu 8.10 mascot"></p><p>于 2008 年 10 月 30 日发布。</p><p>Intrepid 意味着<strong>无所畏惧</strong>、冒险的。</p><p><ruby>野山羊<rt> Ibex </rt></ruby>，以雄性的大弯角为特征，在前面形成像横向的脊那样。它主要分布于欧亚大陆、北非和东非。</p><h3 id="ubuntu-8-04-lts-hardy-heron-坚韧苍鹭" tabindex="-1">Ubuntu 8.04 LTS Hardy Heron（坚韧苍鹭） <a class="header-anchor" href="#ubuntu-8-04-lts-hardy-heron-坚韧苍鹭" aria-label="Permalink to “Ubuntu 8.04 LTS Hardy Heron（坚韧苍鹭）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-8-04-mascot.jpg" alt="Ubuntu 8.04 mascot"></p><p>于 2008 年 4 月 24 日发布。</p><p>这个版本是第一个吉祥物出现在其默认壁纸上的 Ubuntu 版本。</p><p>Hardy 意味着能够<strong>忍受</strong>困难条件的、强大的。</p><p><ruby>苍鹭<rt> Heron </rt></ruby>，是一种长腿、长颈、生活在淡水和沿海的鸟类。</p><h3 id="ubuntu-7-10-gutsy-gibbon-阵风长臂猿" tabindex="-1">Ubuntu 7.10 Gutsy Gibbon（阵风长臂猿） <a class="header-anchor" href="#ubuntu-7-10-gutsy-gibbon-阵风长臂猿" aria-label="Permalink to “Ubuntu 7.10 Gutsy Gibbon（阵风长臂猿）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-7-10-mascot.jpg" alt="Ubuntu 7.10 mascot"></p><p>于 2007 年 10 月 18 日发布。</p><p>Gusty 表示以<strong>阵风</strong>的方式吹动。</p><p><ruby>长臂猿<rt> Gibbon </rt></ruby>，是一种猿类，它们生活在孟加拉国东部、印度东北部、中国南部和印度尼西亚的亚热带和热带雨林地区。</p><h3 id="ubuntu-7-04-feisty-fawn-活泼小鹿" tabindex="-1">Ubuntu 7.04 Feisty Fawn（活泼小鹿） <a class="header-anchor" href="#ubuntu-7-04-feisty-fawn-活泼小鹿" aria-label="Permalink to “Ubuntu 7.04 Feisty Fawn（活泼小鹿）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-7-04-mascot.jpg" alt="Ubuntu 7.04 mascot"></p><p>于 2007 年 4 月 19 日发布。</p><p>Feisty 意味着<strong>小而坚定</strong>的。</p><p><ruby>小鹿<rt> Fawn </rt></ruby>，指的是第一年刚出生的小鹿。</p><h3 id="ubuntu-6-10-edgy-eft-紧张水蜥" tabindex="-1">Ubuntu 6.10 Edgy Eft（紧张水蜥） <a class="header-anchor" href="#ubuntu-6-10-edgy-eft-紧张水蜥" aria-label="Permalink to “Ubuntu 6.10 Edgy Eft（紧张水蜥）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-6-10-mascot.jpg" alt="Ubuntu 6.10 mascot"></p><p>于 2006 年 10 月 26 日发布。</p><p>Edgy 的意思是<strong>紧张的</strong>。</p><p><ruby>水蜥<rt> Eft </rt></ruby>，是蝾螈的陆生幼年期。蝾螈是一种蜥蜴，它具有三个不同的发育生命阶段：水生幼虫、陆生幼体和成体。</p><p>所以水蜥指的是一个青年的蝾螈。</p><h3 id="ubuntu-6-06-dapper-drake-整洁公鸭" tabindex="-1">Ubuntu 6.06 Dapper Drake（整洁公鸭） <a class="header-anchor" href="#ubuntu-6-06-dapper-drake-整洁公鸭" aria-label="Permalink to “Ubuntu 6.06 Dapper Drake（整洁公鸭）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-6-06-mascot.jpg" alt="Ubuntu 6.06 mascot"></p><p>于 2006 年 6 月 1 日发布。</p><p>Dapper 的意思是衣着整洁，<strong>外表整洁的</strong>。</p><p><ruby>公鸭<rt> Drake </rt></ruby>，是完全性成熟的成年雄性鸭子。</p><h3 id="ubuntu-5-10-breezy-badger-微风之獾" tabindex="-1">Ubuntu 5.10 Breezy Badger（微风之獾） <a class="header-anchor" href="#ubuntu-5-10-breezy-badger-微风之獾" aria-label="Permalink to “Ubuntu 5.10 Breezy Badger（微风之獾）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-5-10-mascot.jpg" alt="Ubuntu 5.10 mascot"></p><p>于 2005 年 10 月 12 日发布。</p><p>Breezy 的意思是有<strong>微风</strong>的。</p><p><ruby>獾<rt> Badger </rt></ruby>，一种是短腿的杂食动物，经常蹲下身挤在一起。</p><h3 id="ubuntu-5-04-hoary-hedgehog-灰白刺猬" tabindex="-1">Ubuntu 5.04 Hoary Hedgehog（灰白刺猬） <a class="header-anchor" href="#ubuntu-5-04-hoary-hedgehog-灰白刺猬" aria-label="Permalink to “Ubuntu 5.04 Hoary Hedgehog（灰白刺猬）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-5-04-mascot.jpg" alt="Ubuntu 5.04 mascot"></p><p>于 2005 年 4 月 8 日发布。</p><p>Hoary 是<strong>灰白色的</strong>意思。</p><p><ruby>刺猬<rt> Hedgehogis </rt></ruby>，是一种多刺的哺乳动物，遍布于欧洲、亚洲和非洲的部分地区，并引入到了新西兰。</p><h3 id="ubuntu-4-10-warty-warthog-有疣疣猪" tabindex="-1">Ubuntu 4.10 : Warty Warthog（有疣疣猪） <a class="header-anchor" href="#ubuntu-4-10-warty-warthog-有疣疣猪" aria-label="Permalink to “Ubuntu 4.10 : Warty Warthog（有疣疣猪）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-4-10-mascot.jpg" alt="Ubuntu 4.10 mascot"></p><p>于 2004 年 10 月 20 日发布。</p><p>Ubuntu 就是从这个版本开始的。</p><p>Wart 是由病毒引起的一种小的、坚硬的、良性的皮肤生长物。Warty 的意思是<strong>长满疣的</strong>。</p><p><ruby>疣猪<rt> Warthog </rt></ruby>，是猪科的一种野生动物，它是在撒哈拉以南非洲的草原、稀树草原和林地中被发现的。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>本文有没有让 Ubuntu 用户了解了更多知识呢？从技术上讲，并没有，但回顾历史是件好事。如果你多年来一直是 Ubuntu 用户，那么这篇文章可能会引发你的怀旧之情。</p><p>Ubuntu 9.04 是我第一次尝试 Linux 桌面。如果我没记错的话，那是在 2009 年 9 月下旬。仅仅几周后，我的系统就升级到了 Ubuntu 9.10。那些天我经常在 Ubuntu 论坛上浏览，探索这个新的操作系统，并学习新的东西。</p><p>那么，这篇文章有没有勾起你的一些美好的回忆呢？你的第一个 Ubuntu 版本又是哪个呢？在评论区中分享你的 Ubuntu 使用经历吧。</p><hr>',206)),s("p",null,[t[4]||(t[4]=u("via: ",-1)),r(a,{href:"https://itsfoss.com/all-Ubuntu-mascots/"},{default:n(()=>[...t[3]||(t[3]=[u("https://itsfoss.com/all-Ubuntu-mascots/",-1)])]),_:1})]),s("p",null,[t[9]||(t[9]=u("作者：",-1)),r(a,{href:"https://itsfoss.com/author/abhishek/"},{default:n(()=>[...t[5]||(t[5]=[u("Abhishek Prakash",-1)])]),_:1}),t[10]||(t[10]=u(" 选题：",-1)),r(a,{href:"https://github.com/lkxed"},{default:n(()=>[...t[6]||(t[6]=[u("lkxed",-1)])]),_:1}),t[11]||(t[11]=u(" 译者：",-1)),r(a,{href:"https://github.com/chai001125"},{default:n(()=>[...t[7]||(t[7]=[u("chai001125",-1)])]),_:1}),t[12]||(t[12]=u(" 校对：",-1)),r(a,{href:"https://github.com/wxy"},{default:n(()=>[...t[8]||(t[8]=[u("wxy",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=u("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[13]||(t[13]=[u("LCTT",-1)])]),_:1}),t[16]||(t[16]=u(" 原创编译，",-1)),r(a,{href:"https://linux.cn/"},{default:n(()=>[...t[14]||(t[14]=[u("Linux中国",-1)])]),_:1}),t[17]||(t[17]=u(" 荣誉推出",-1))])])}const x=p(l,[["render",c]]);export{k as __pageData,x as default};
